<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $lab->title }} | SQL Lab</title></head><body class="min-h-screen bg-slate-100 p-6 text-slate-900"><main class="mx-auto max-w-6xl"><a href="{{ route('sql-lab.index') }}">← SQL Lab</a><section class="mt-5 rounded-2xl bg-white p-6"><p class="text-sm font-semibold uppercase text-teal-700">{{ ucfirst($lab->mode) }} · Simulasi lokal</p><h1 class="mt-2 text-3xl font-bold">{{ $lab->title }}</h1><p class="mt-2 text-slate-600">{{ $lab->description }}</p><p class="mt-3 text-sm text-amber-700">Run query: menunggu engine SQL final.</p><h2 class="mt-6 text-xl font-bold">Schema starter</h2><pre class="mt-2 overflow-auto rounded-lg bg-slate-900 p-4 text-sm text-white">{{ json_encode($lab->schema_json, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE) }}</pre></section><section class="mt-6 space-y-4">@foreach($lab->steps as $step)<article class="rounded-2xl bg-white p-6"><p class="text-sm text-slate-500">Langkah {{ $loop->iteration }}</p><h2 class="mt-1 text-xl font-bold">{{ $step->title }}</h2><p class="mt-2">{{ $step->instruction }}</p><textarea data-query-key="radix-lab-{{ $lab->id }}-step-{{ $step->id }}" rows="8" class="mt-4 w-full rounded-lg border bg-slate-950 p-4 font-mono text-sm text-white" placeholder="Tulis query SQL di sini..."></textarea><p class="mt-2 text-sm text-slate-500">Expected result: {{ json_encode($step->expected_result_json) }}</p><button type="button" disabled class="mt-4 rounded-lg bg-slate-300 px-5 py-3 text-slate-600">Run (menunggu engine SQL)</button></article>@endforeach</section></main><script>document.querySelectorAll('[data-query-key]').forEach((editor) => { const key = editor.dataset.queryKey; editor.value = localStorage.getItem(key) || ''; editor.addEventListener('input', () => localStorage.setItem(key, editor.value)); });</script></body></html>
